{
  "name": "pairwise_advantage_cost_gap_loss",
  "intuition": "This loss combines advantage signals with cost gaps to focus on pairs where the advantage indicates better preference, scaled by the cost gap to emphasize meaningful differences. Using logsigmoid on advantage signals ensures stable gradients, while incorporating cost gap normalizes the importance of each pair, encouraging the model to prioritize genuinely better options with significant advantage and cost differences.",
  "pseudocode": "loss = mean(-logsigmoid(advantage_w - advantage_l) * clamp(cost_gap, min=0, max=large_value))",
  "hyperparams": {
    "paradigm_family": "preference",
    "signal_family": "advantage",
    "link_family": "logarithmic",
    "agg_family": "pairwise",
    "constraint_family": "cost"
  },
  "operators_used": ["logsigmoid", "clamp", "mean"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    adv_w = batch['advantage_w']\n    adv_l = batch['advantage_l']\n    cost_gap = batch.get('cost_gap', None)\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    # Compute pairwise advantage difference\n    advantage_diff = ops.sub(adv_w, adv_l)\n    # Stabilize cost gap if necessary\n    normalized_cost_gap = ops.clamp(cost_gap, 0, 1e6)\n    # Compute logsigmoid on advantage difference\n    logsig_adv = ops.logsigmoid(advantage_diff)\n    # Weight by cost gap\n    weighted = ops.mul(logsig_adv, normalized_cost_gap)\n    # Final loss as mean over batch\n    loss = ops.mean(ops.neg(weighted))\n    return loss"
}

{
  "name": "loss_advantage_tanh_penalty",
  "intuition": "Use a nonlinear tanh transformation of the advantage difference combined with a pairwise hinge constraint to penalize violations softly, promoting margin-based preference learning with saturation and robust gradients.",
  "pseudocode": "diff = log_prob_w - log_prob_l\npenalty = relu(margin - diff)\ntransformed = tanh(scale * advantage_gap)\nloss = mean(weight * (max(0, penalty) + 1 - transformed))",
  "hyperparams": {
    "paradigm_family": "pairwise_hinge_saturation",
    "signal_family": "advantage_gap",
    "link_family": "tanh_plus_relu",
    "agg_family": "mean",
    "constraint_family": "margin_positivity"
  },
  "operators_used": ["sub", "relu", "tanh", "mul", "add", "max", "mean"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', ops.ones_like(lpw))\n    adv_gap = batch['advantage_gap']\n    margin = float(extra.get('margin', 0.3))\n    scale = float(extra.get('scale', 5.0))\n\n    diff = ops.sub(lpw, lpl)  # difference in log probs\n    penalty = ops.relu(margin - diff)  # hinge penalty if margin violated\n    transformed = ops.tanh(ops.mul(scale, adv_gap))  # saturating transform of advantage_gap\n\n    base_loss = ops.add(penalty, ops.sub(1.0, transformed))\n    weighted_loss = ops.mul(weight, base_loss)\n    return ops.mean(weighted_loss)"
}

{
  "name": "pairwise_advantage_gap_loss",
  "intuition": "This loss encourages the model to assign higher likelihood to pairs where the advantage difference (advantage_w - advantage_l) is maximized, promoting preference for better options. Using advantage gaps directly aligns with preference signals that quantify candidate quality differences, making the loss sensitive to relative improvements. It leverages the advantage gap as a pairwise comparison measure, fostering optimized ranking in RL4CO.",
  "pseudocode": "loss = -mean(logsigmoid(advantage_w - advantage_l)) + regularization",
  "hyperparams": {
    "paradigm_family": "pairwise",
    "signal_family": "advantage",
    "link_family": "sigmoid",
    "agg_family": "mean",
    "constraint_family": "preference",
    "other_hparams": ""
  },
  "operators_used": ["logsigmoid"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    advantage_gap = batch.get('advantage_gap', None)\n    if advantage_gap is None:\n        # fallback if advantage_gap is missing\n        advantage_gap = ops.sub(batch['advantage_w'], batch['advantage_l'])\n    # compute pairwise loss using logsigmoid\n    diff = advantage_gap\n    loss_vals = -ops.logsigmoid(diff)\n    weighted_loss = ops.mul(loss_vals, batch['weight'])\n    return ops.mean(weighted_loss)"
}

