  "code": "def generated_loss(batch, model_output, extra):\n    advantage_w = batch[\"advantage_w\"]\n    advantage_l = batch[\"advantage_l\"]\n    log_prob_w = batch[\"log_prob_w\"]\n    log_prob_l = batch[\"log_prob_l\"]\n    weight = batch.get(\"weight\", None)\n    diff = ops.sub(advantage_w, advantage_l)\n    loss_per_pair = ops.logsigmoid(diff)\n    if weight is not None:\n        loss_scaled = ops.mul(loss_per_pair, weight)\n        return ops.mean(loss_scaled)\n    else:\n        return ops.mean(loss_per_pair)"
