  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    cost_gap = batch['cost_gap']\n    # Compute energy as difference of log probs minus cost_gap scaled by beta\n    beta = 1.0\n    energy = ops.sub(ops.sub(lpl, lpw), ops.mul(beta, cost_gap))\n    # Clamp energy to [-10, 10] for numerical stability in sigmoid\n    energy_clamped = ops.clamp(energy, -10.0, 10.0)\n    loss = ops.sigmoid(energy_clamped)\n    if weight is not None:\n        loss = ops.mul(loss, weight)\n    return ops.mean(loss)"
