{
  "name": "loss_advantage_tanh_penalty_sum",
  "intuition": "Preserve the nonlinear tanh transformation of advantage difference with hinge penalty but aggregate losses by summation instead of mean to emphasize total violation magnitude over average.",
  "pseudocode": "diff = log_prob_w - log_prob_l\npenalty = relu(margin - diff)\ntransformed = tanh(scale * advantage_gap)\nloss = sum(weight * (max(0, penalty) + 1 - transformed))",
  "hyperparams": {
    "paradigm_family": "pairwise_hinge_saturation",
    "signal_family": "advantage_gap",
    "link_family": "tanh_plus_relu",
    "agg_family": "sum",
    "constraint_family": "margin_positivity"
  },
  "operators_used": ["sub", "relu", "tanh", "mul", "add", "max", "sum"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', ops.ones_like(lpw))\n    adv_gap = batch['advantage_gap']\n    margin = float(extra.get('margin', 0.3))\n    scale = float(extra.get('scale', 5.0))\n\n    diff = ops.sub(lpw, lpl)\n    penalty = ops.relu(ops.sub(margin, diff))\n    transformed = ops.tanh(ops.mul(scale, adv_gap))\n\n    base_loss = ops.add(penalty, ops.sub(1.0, transformed))\n    weighted_loss = ops.mul(weight, base_loss)\n    return ops.sum(weighted_loss)"
